package dwg

// R2004+ header XOR cipher (spec §4.1).
//
// The 0x6C bytes starting at file offset 0x80 are XORed against a
// deterministic 0x6C-byte magic sequence generated by a Microsoft-flavor
// linear congruential generator seeded with 1 (the same LCG Visual C++
// rand() uses).

// MagicLen is the length of the R2004+ XOR cipher stream — 0x6C bytes.
const MagicLen = 0x6C

// magicSequence returns the 108-byte R2004+ XOR magic sequence. It is
// identical on every call because the LCG seed is always 1.
func magicSequence() [MagicLen]byte {
	var out [MagicLen]byte
	seed := uint32(1)
	for i := range out {
		seed = seed*0x000343FD + 0x00269EC3
		out[i] = byte((seed >> 0x10) & 0xFF)
	}
	return out
}

// xorInPlace XOR-decrypts (or re-encrypts — XOR is its own inverse) a
// 0x6C-byte block in place.
func xorInPlace(block []byte) {
	magic := magicSequence()
	for i := range block {
		if i >= len(magic) {
			break
		}
		block[i] ^= magic[i]
	}
}

// sectionPageMask is the R2018+ encrypted section-page-header mask
// (spec §4.6): 0x4164536B XOR offset, where offset is the file position
// of the 32-byte page header.
func sectionPageMask(offset uint32) uint32 {
	return 0x4164536B ^ offset
}
